/* TAS017-TAS022: mantenimiento y aplicación transaccional de perfiles. */
USE [cxView];
GO
CREATE OR ALTER PROCEDURE dbo.SP_TAS017_CONSULTAR_PERFILES @idperfil varchar(36)=NULL,@idapp varchar(36)=NULL,@nombre varchar(20)=NULL,@estado varchar(1)=NULL AS
SELECT p.IDPERFIL AS ID,p.IDAPP,p.NOMPERFIL AS NAME,p.DESCPERFIL AS DESCRIPTION,p.ESTPERFIL AS STATUS,p.SACRG AS ISRECORDACTIVE,p.CUSCRT AS CREATEDBY,p.FCHHRACRT AS CREATEDAT,p.CULUSA AS UPDATEDBY,p.FCHHRAACT AS UPDATEDAT
FROM dbo.TAS017 p WHERE (@idperfil IS NULL OR p.IDPERFIL=@idperfil) AND (@idapp IS NULL OR p.IDAPP=@idapp) AND (@nombre IS NULL OR p.NOMPERFIL LIKE '%'+@nombre+'%') AND (@estado IS NULL OR p.ESTPERFIL=@estado) ORDER BY p.NOMPERFIL;
GO
CREATE OR ALTER PROCEDURE dbo.SP_TAS017_CREAR_PERFIL @idapp varchar(36)=NULL,@nombre varchar(20),@descripcion varchar(100)=NULL,@usuario varchar(20) AS
BEGIN SET NOCOUNT ON; IF NULLIF(LTRIM(RTRIM(@nombre)),'') IS NULL THROW 51001,'El nombre del perfil es obligatorio.',1; IF EXISTS(SELECT 1 FROM dbo.TAS017 WHERE IDAPP= @idapp AND NOMPERFIL=LTRIM(RTRIM(@nombre)) AND SACRG=1) THROW 51002,'Ya existe un perfil con ese nombre.',1; DECLARE @id varchar(36)=CONVERT(varchar(36),NEWID()); INSERT dbo.TAS017(IDPERFIL,IDAPP,NOMPERFIL,DESCPERFIL,ESTPERFIL,SACRG,CUSCRT,FCHHRACRT) VALUES(@id,@idapp,LTRIM(RTRIM(@nombre)),NULLIF(LTRIM(RTRIM(@descripcion)),''),'A',1,@usuario,SYSDATETIME()); EXEC dbo.SP_TAS017_CONSULTAR_PERFILES @idperfil=@id; END;
GO
CREATE OR ALTER PROCEDURE dbo.SP_TAS017_ACTUALIZAR_PERFIL @idperfil varchar(36),@idapp varchar(36)=NULL,@nombre varchar(20),@descripcion varchar(100)=NULL,@estado varchar(1),@usuario varchar(20) AS
BEGIN UPDATE dbo.TAS017 SET IDAPP=@idapp,NOMPERFIL=LTRIM(RTRIM(@nombre)),DESCPERFIL=NULLIF(LTRIM(RTRIM(@descripcion)),''),ESTPERFIL=UPPER(@estado),CULUSA=@usuario,FCHHRAACT=SYSDATETIME() WHERE IDPERFIL=@idperfil AND SACRG=1; IF @@ROWCOUNT=0 THROW 51003,'Perfil no encontrado.',1; EXEC dbo.SP_TAS017_CONSULTAR_PERFILES @idperfil=@idperfil; END;
GO
CREATE OR ALTER PROCEDURE dbo.SP_TAS017_DAR_BAJA_PERFIL @idperfil varchar(36),@usuario varchar(20) AS
BEGIN UPDATE dbo.TAS017 SET ESTPERFIL='I',SACRG=0,CULUSA=@usuario,FCHHRAACT=SYSDATETIME() WHERE IDPERFIL=@idperfil AND SACRG=1; IF @@ROWCOUNT=0 THROW 51004,'Perfil no encontrado.',1; SELECT 1 AS FILASAFECTADAS; END;
GO
/* Listados por perfil. */
CREATE OR ALTER PROCEDURE dbo.SP_TAS018_LISTAR_MODULOS_PERFIL @idperfil varchar(36) AS SELECT m.IDMOD AS RESOURCEID,m.IDAPP,m.NOMMOD AS NAME,m.DESCMOD AS DESCRIPTION,CAST(CASE WHEN a.IDPRFLMOD IS NULL THEN 0 ELSE 1 END AS bit) AS ASSIGNED,a.IDPRFLMOD AS ACCESSID FROM dbo.TAS007 m LEFT JOIN dbo.TAS018 a ON a.IDMOD=m.IDMOD AND a.IDPERFIL=@idperfil AND a.ESTPRFLMOD='A' AND a.SACRG=1 WHERE m.ESTMOD='A' AND m.SACRG=1;
GO
CREATE OR ALTER PROCEDURE dbo.SP_TAS019_LISTAR_MENUS_PERFIL @idperfil varchar(36),@idmod varchar(36)=NULL AS SELECT m.IDMENU AS RESOURCEID,m.IDMOD,m.NOMMENU AS NAME,m.DESCMENU AS DESCRIPTION,CAST(CASE WHEN a.IDPRFLMNU IS NULL THEN 0 ELSE 1 END AS bit) AS ASSIGNED,a.IDPRFLMNU AS ACCESSID FROM dbo.TAS009 m LEFT JOIN dbo.TAS019 a ON a.IDMENU=m.IDMENU AND a.IDPERFIL=@idperfil AND a.ESTPRFLMNU='A' AND a.SACRG=1 WHERE m.ESTMENU='A' AND m.SACRG=1 AND (@idmod IS NULL OR m.IDMOD=@idmod);
GO
CREATE OR ALTER PROCEDURE dbo.SP_TAS020_LISTAR_SUBMENUS_PERFIL @idperfil varchar(36),@idmenu varchar(36)=NULL AS SELECT s.IDSUBMENU AS RESOURCEID,s.IDMENU,s.NOMSUBMNU AS NAME,s.DESCSUBMNU AS DESCRIPTION,CAST(CASE WHEN a.IDPRFLSM IS NULL THEN 0 ELSE 1 END AS bit) AS ASSIGNED,a.IDPRFLSM AS ACCESSID FROM dbo.TAS011 s LEFT JOIN dbo.TAS020 a ON a.IDSUBMENU=s.IDSUBMENU AND a.IDPERFIL=@idperfil AND a.ESTPRFLMNU='A' AND a.SACRG=1 WHERE s.ESTSUBMNU='A' AND s.SACRG=1 AND (@idmenu IS NULL OR s.IDMENU=@idmenu);
GO
CREATE OR ALTER PROCEDURE dbo.SP_TAS021_LISTAR_SEGUNDO_NIVEL_PERFIL @idperfil varchar(36),@idsubmenu varchar(36)=NULL AS SELECT s.IDSMSN AS RESOURCEID,s.IDSUBMENU,s.NOMSMSN AS NAME,s.DESCSMSN AS DESCRIPTION,CAST(CASE WHEN a.IDPRFLSMSN IS NULL THEN 0 ELSE 1 END AS bit) AS ASSIGNED,a.IDPRFLSMSN AS ACCESSID FROM dbo.TAS013 s LEFT JOIN dbo.TAS021 a ON a.IDSMSN=s.IDSMSN AND a.IDPERFIL=@idperfil AND a.ESTPRFLMNU='A' AND a.SACRG=1 WHERE s.ESTSMSN='A' AND s.SACRG=1 AND (@idsubmenu IS NULL OR s.IDSUBMENU=@idsubmenu);
GO
CREATE OR ALTER PROCEDURE dbo.SP_TAS022_LISTAR_OPCIONES_PERFIL @idperfil varchar(36),@idsubmenu varchar(36)=NULL,@idsmsn varchar(36)=NULL AS SELECT o.IDOPCFOMR AS RESOURCEID,o.IDSUBMENU,o.IDSMSN,o.NOMOPC AS CODE,o.DESCOPC AS DESCRIPTION,CAST(CASE WHEN a.IDPRFLOPC IS NULL THEN 0 ELSE 1 END AS bit) AS ASSIGNED,a.IDPRFLOPC AS ACCESSID FROM dbo.TAS015 o LEFT JOIN dbo.TAS022 a ON a.IDOPCFOMR=o.IDOPCFOMR AND a.IDPERFIL=@idperfil AND a.ESTPRFLMNU='A' AND a.SACRG=1 WHERE o.ESTOPC='A' AND o.SACRG=1 AND (@idsubmenu IS NULL OR o.IDSUBMENU=@idsubmenu) AND (@idsmsn IS NULL OR o.IDSMSN=@idsmsn);
GO
/* Idempotent assignment procedures: parent resource must be active. */
CREATE OR ALTER PROCEDURE dbo.SP_TAS018_ASIGNAR_MODULO_PERFIL @idperfil varchar(36),@idmod varchar(36),@usuario varchar(20) AS BEGIN IF NOT EXISTS(SELECT 1 FROM dbo.TAS017 WHERE IDPERFIL=@idperfil AND ESTPERFIL='A' AND SACRG=1) THROW 51010,'Perfil inválido.',1; IF NOT EXISTS(SELECT 1 FROM dbo.TAS007 WHERE IDMOD=@idmod AND ESTMOD='A' AND SACRG=1) THROW 51011,'Módulo inválido.',1; IF EXISTS(SELECT 1 FROM dbo.TAS018 WHERE IDPERFIL=@idperfil AND IDMOD=@idmod) UPDATE dbo.TAS018 SET ESTPRFLMOD='A',SACRG=1,CULUSA=@usuario,FCHHRAACT=SYSDATETIME() WHERE IDPERFIL=@idperfil AND IDMOD=@idmod; ELSE INSERT dbo.TAS018 VALUES(CONVERT(varchar(36),NEWID()),@idperfil,@idmod,'A',1,@usuario,SYSDATETIME(),NULL,NULL); EXEC dbo.SP_TAS018_LISTAR_MODULOS_PERFIL @idperfil; END;
GO
CREATE OR ALTER PROCEDURE dbo.SP_TAS019_ASIGNAR_MENU_PERFIL @idperfil varchar(36),@idmenu varchar(36),@usuario varchar(20) AS BEGIN DECLARE @idmod varchar(36)=(SELECT IDMOD FROM dbo.TAS009 WHERE IDMENU=@idmenu AND ESTMENU='A' AND SACRG=1); IF @idmod IS NULL THROW 51012,'Menú inválido.',1; IF NOT EXISTS(SELECT 1 FROM dbo.TAS018 WHERE IDPERFIL=@idperfil AND IDMOD=@idmod AND ESTPRFLMOD='A' AND SACRG=1) THROW 51013,'Primero asigne el módulo al perfil.',1; IF EXISTS(SELECT 1 FROM dbo.TAS019 WHERE IDPERFIL=@idperfil AND IDMENU=@idmenu) UPDATE dbo.TAS019 SET ESTPRFLMNU='A',SACRG=1,CULUSA=@usuario,FCHHRAACT=SYSDATETIME() WHERE IDPERFIL=@idperfil AND IDMENU=@idmenu; ELSE INSERT dbo.TAS019 VALUES(CONVERT(varchar(36),NEWID()),@idperfil,@idmenu,'A',1,@usuario,SYSDATETIME(),NULL,NULL); EXEC dbo.SP_TAS019_LISTAR_MENUS_PERFIL @idperfil; END;
GO
CREATE OR ALTER PROCEDURE dbo.SP_TAS020_ASIGNAR_SUBMENU_PERFIL @idperfil varchar(36),@idsubmenu varchar(36),@usuario varchar(20) AS BEGIN DECLARE @idmenu varchar(36)=(SELECT IDMENU FROM dbo.TAS011 WHERE IDSUBMENU=@idsubmenu AND ESTSUBMNU='A' AND SACRG=1); IF @idmenu IS NULL THROW 51014,'Submenú inválido.',1; IF NOT EXISTS(SELECT 1 FROM dbo.TAS019 WHERE IDPERFIL=@idperfil AND IDMENU=@idmenu AND ESTPRFLMNU='A' AND SACRG=1) THROW 51015,'Primero asigne el menú al perfil.',1; IF EXISTS(SELECT 1 FROM dbo.TAS020 WHERE IDPERFIL=@idperfil AND IDSUBMENU=@idsubmenu) UPDATE dbo.TAS020 SET ESTPRFLMNU='A',SACRG=1,CULUSA=@usuario,FCHHRAACT=SYSDATETIME() WHERE IDPERFIL=@idperfil AND IDSUBMENU=@idsubmenu; ELSE INSERT dbo.TAS020 VALUES(CONVERT(varchar(36),NEWID()),@idperfil,@idsubmenu,'A',1,@usuario,SYSDATETIME(),NULL,NULL); EXEC dbo.SP_TAS020_LISTAR_SUBMENUS_PERFIL @idperfil; END;
GO
CREATE OR ALTER PROCEDURE dbo.SP_TAS021_ASIGNAR_SEGUNDO_NIVEL_PERFIL @idperfil varchar(36),@idsmsn varchar(36),@usuario varchar(20) AS BEGIN DECLARE @idsubmenu varchar(36)=(SELECT IDSUBMENU FROM dbo.TAS013 WHERE IDSMSN=@idsmsn AND ESTSMSN='A' AND SACRG=1); IF @idsubmenu IS NULL THROW 51016,'Segundo nivel inválido.',1; IF NOT EXISTS(SELECT 1 FROM dbo.TAS020 WHERE IDPERFIL=@idperfil AND IDSUBMENU=@idsubmenu AND ESTPRFLMNU='A' AND SACRG=1) THROW 51017,'Primero asigne el submenú al perfil.',1; IF EXISTS(SELECT 1 FROM dbo.TAS021 WHERE IDPERFIL=@idperfil AND IDSMSN=@idsmsn) UPDATE dbo.TAS021 SET ESTPRFLMNU='A',SACRG=1,CULUSA=@usuario,FCHHRAACT=SYSDATETIME() WHERE IDPERFIL=@idperfil AND IDSMSN=@idsmsn; ELSE INSERT dbo.TAS021 VALUES(CONVERT(varchar(36),NEWID()),@idperfil,@idsmsn,'A',1,@usuario,SYSDATETIME(),NULL,NULL); EXEC dbo.SP_TAS021_LISTAR_SEGUNDO_NIVEL_PERFIL @idperfil; END;
GO
CREATE OR ALTER PROCEDURE dbo.SP_TAS022_ASIGNAR_OPCION_PERFIL @idperfil varchar(36),@idopcfomr varchar(36),@usuario varchar(20) AS BEGIN DECLARE @idsubmenu varchar(36)=(SELECT IDSUBMENU FROM dbo.TAS015 WHERE IDOPCFOMR=@idopcfomr AND ESTOPC='A' AND SACRG=1),@idsmsn varchar(36)=(SELECT IDSMSN FROM dbo.TAS015 WHERE IDOPCFOMR=@idopcfomr); IF @idsubmenu IS NULL AND @idsmsn IS NULL THROW 51018,'Opción inválida.',1; IF @idsubmenu IS NOT NULL AND NOT EXISTS(SELECT 1 FROM dbo.TAS020 WHERE IDPERFIL=@idperfil AND IDSUBMENU=@idsubmenu AND ESTPRFLMNU='A' AND SACRG=1) THROW 51019,'Primero asigne el submenú al perfil.',1; IF @idsmsn IS NOT NULL AND NOT EXISTS(SELECT 1 FROM dbo.TAS021 WHERE IDPERFIL=@idperfil AND IDSMSN=@idsmsn AND ESTPRFLMNU='A' AND SACRG=1) THROW 51020,'Primero asigne el segundo nivel al perfil.',1; IF EXISTS(SELECT 1 FROM dbo.TAS022 WHERE IDPERFIL=@idperfil AND IDOPCFOMR=@idopcfomr) UPDATE dbo.TAS022 SET ESTPRFLMNU='A',SACRG=1,CULUSA=@usuario,FCHHRAACT=SYSDATETIME() WHERE IDPERFIL=@idperfil AND IDOPCFOMR=@idopcfomr; ELSE INSERT dbo.TAS022 VALUES(CONVERT(varchar(36),NEWID()),@idperfil,@idopcfomr,'A',1,@usuario,SYSDATETIME(),NULL,NULL); EXEC dbo.SP_TAS022_LISTAR_OPCIONES_PERFIL @idperfil; END;
GO
CREATE OR ALTER PROCEDURE dbo.SP_TAS_PERFIL_RETIRAR_ASIGNACION @accessid varchar(36),@usuario varchar(20) AS BEGIN DECLARE @sql nvarchar(max)=N''; IF EXISTS(SELECT 1 FROM dbo.TAS018 WHERE IDPRFLMOD=@accessid) UPDATE dbo.TAS018 SET ESTPRFLMOD='I',SACRG=0,CULUSA=@usuario,FCHHRAACT=SYSDATETIME() WHERE IDPRFLMOD=@accessid; ELSE IF EXISTS(SELECT 1 FROM dbo.TAS019 WHERE IDPRFLMNU=@accessid) UPDATE dbo.TAS019 SET ESTPRFLMNU='I',SACRG=0,CULUSA=@usuario,FCHHRAACT=SYSDATETIME() WHERE IDPRFLMNU=@accessid; ELSE IF EXISTS(SELECT 1 FROM dbo.TAS020 WHERE IDPRFLSM=@accessid) UPDATE dbo.TAS020 SET ESTPRFLMNU='I',SACRG=0,CULUSA=@usuario,FCHHRAACT=SYSDATETIME() WHERE IDPRFLSM=@accessid; ELSE IF EXISTS(SELECT 1 FROM dbo.TAS021 WHERE IDPRFLSMSN=@accessid) UPDATE dbo.TAS021 SET ESTPRFLMNU='I',SACRG=0,CULUSA=@usuario,FCHHRAACT=SYSDATETIME() WHERE IDPRFLSMSN=@accessid; ELSE IF EXISTS(SELECT 1 FROM dbo.TAS022 WHERE IDPRFLOPC=@accessid) UPDATE dbo.TAS022 SET ESTPRFLMNU='I',SACRG=0,CULUSA=@usuario,FCHHRAACT=SYSDATETIME() WHERE IDPRFLOPC=@accessid; ELSE THROW 51021,'Asignación de perfil no encontrada.',1; SELECT 1 AS FILASAFECTADAS; END;
GO
CREATE OR ALTER PROCEDURE dbo.SP_TAS017_APLICAR_PERFIL_USUARIO @idperfil varchar(36),@iduser varchar(36),@usuario varchar(20) AS
BEGIN SET NOCOUNT ON; SET XACT_ABORT ON; BEGIN TRAN; BEGIN TRY
 IF NOT EXISTS(SELECT 1 FROM dbo.TAS017 WHERE IDPERFIL=@idperfil AND ESTPERFIL='A' AND SACRG=1) THROW 51030,'Perfil inválido.',1; IF NOT EXISTS(SELECT 1 FROM dbo.TAS006 WHERE IDUSER=@iduser AND ESTUSER='A' AND SACRG=1) THROW 51031,'Usuario inválido.',1;
 DELETE FROM dbo.TAS016 WHERE IDUSER=@iduser; DELETE FROM dbo.TAS014 WHERE IDUSER=@iduser; DELETE FROM dbo.TAS012 WHERE IDUSER=@iduser; DELETE FROM dbo.TAS010 WHERE IDUSER=@iduser; DELETE FROM dbo.TAS008 WHERE IDUSER=@iduser;
 INSERT dbo.TAS008(IDMODUSU,IDMOD,IDUSER,ESTMODUSU,SACRG,CUSCRT,FCHHRACRT) SELECT CONVERT(varchar(36),NEWID()),IDMOD,@iduser,'A',1,@usuario,SYSDATETIME() FROM dbo.TAS018 WHERE IDPERFIL=@idperfil AND ESTPRFLMOD='A' AND SACRG=1;
 INSERT dbo.TAS010(IDMENUUSU,IDMENU,IDUSER,ESTMENUUSU,SACRG,CUSCRT,FCHHRACRT) SELECT CONVERT(varchar(36),NEWID()),IDMENU,@iduser,'A',1,@usuario,SYSDATETIME() FROM dbo.TAS019 WHERE IDPERFIL=@idperfil AND ESTPRFLMNU='A' AND SACRG=1;
 INSERT dbo.TAS012(IDSMUSER,IDSUBMENU,IDUSER,ESTSMUSER,SACRG,CUSCRT,FCHHRACRT) SELECT CONVERT(varchar(36),NEWID()),IDSUBMENU,@iduser,'A',1,@usuario,SYSDATETIME() FROM dbo.TAS020 WHERE IDPERFIL=@idperfil AND ESTPRFLMNU='A' AND SACRG=1;
 INSERT dbo.TAS014(IDSMSNUSU,IDSMSN,IDUSER,ESTSMSNUSU,SACRG,CUSCRT,FCHHRACRT) SELECT CONVERT(varchar(36),NEWID()),IDSMSN,@iduser,'A',1,@usuario,SYSDATETIME() FROM dbo.TAS021 WHERE IDPERFIL=@idperfil AND ESTPRFLMNU='A' AND SACRG=1;
 INSERT dbo.TAS016(IDOPCFORMUSU,IDOPCFOMR,IDUSER,ESTOPC,SACRG,CUSCRT,FCHHRACRT) SELECT CONVERT(varchar(36),NEWID()),IDOPCFOMR,@iduser,'A',1,@usuario,SYSDATETIME() FROM dbo.TAS022 WHERE IDPERFIL=@idperfil AND ESTPRFLMNU='A' AND SACRG=1;
 COMMIT; SELECT @idperfil AS PROFILEID,@iduser AS USERID,(SELECT COUNT(*) FROM dbo.TAS008 WHERE IDUSER=@iduser) AS MODULES,(SELECT COUNT(*) FROM dbo.TAS010 WHERE IDUSER=@iduser) AS MENUS,(SELECT COUNT(*) FROM dbo.TAS012 WHERE IDUSER=@iduser) AS SUBMENUS,(SELECT COUNT(*) FROM dbo.TAS014 WHERE IDUSER=@iduser) AS SECONDLEVELS,(SELECT COUNT(*) FROM dbo.TAS016 WHERE IDUSER=@iduser) AS OPTIONS;
 END TRY BEGIN CATCH IF @@TRANCOUNT>0 ROLLBACK; THROW; END CATCH END;
GO
